function workDaySet(value) {
  var list = value;
  if (typeof list === 'string') list = list.split(',');
  var set = {}, any = false;
  if (list && typeof list.length === 'number') {
    for (var i = 0; i < list.length; i++) {
      var d = Number(list[i]);
