function moveOf(projectId, moveBlocks, today) {
  var live = null, last = null;
  var list = moveBlocks || [];
  for (var i = 0; i < list.length; i++) {
    var b = list[i];
    if (!b || !b.isMove || b.projectId !== projectId || !parseDay(b.date)) continue;
