var ENV_KEYS = ["billable","building","admin","hobby","dormant"];
var ENV_NAMES = {"billable":"Billable","building":"Building","admin":"Admin and asks","hobby":"Hobby","dormant":"Dormant, worth a nudge"};
function envMark(k) { return 'var(--env-' + k + ')'; }
function envInk(k) { return 'var(--env-' + k + '-ink)'; }
