var projects = Inputs.projects || [];
var today = startOfToday();

var withMove = [];
for (var i = 0; i < projects.length; i++) {
  var p = projects[i];
  // R9 — a finished asset says "fixes only" and stops asking for hours.
  if (!p || !p.move || p.moveStop) continue;
